  {id:'water',title:'حالات الماء وتحولاتها',level:'النشاط العلمي · ابتدائي',duration:45,objective:['يسمي الحالات الثلاث للماء.','يربط الذوبان والتبخر والتجمد بسبب مناسب.','يرسم مخططًا بسيطًا للتحولات.'],prior:'التمييز بين السائل والصلب في الحياة اليومية.',steps:[['وضعية الانطلاق',5,'عرض مكعب ثلج وسؤال: ماذا سيحدث له بعد ساعة؟'],['صياغة الفرضيات',10,'تدوين التفسيرات واختيار ما يمكن اختباره.'],['التجريب',15,'تجربة جماعية مع تسجيل الملاحظات واحترام السلامة.'],['الاستنتاج والتقويم',10,'صياغة الخلاصة ورسم مخطط التحولات.'],['الدعم',5,'إعادة التجربة مع من تعثر.']]},
  {id:'map',title:'قراءة الخريطة: العنوان والرموز والمفتاح',level:'الاجتماعيات · ابتدائي',duration:45,objective:['يحدد عنوان الخريطة ومفتاحها.','يقرأ ثلاثة رموز بالرجوع إلى المفتاح.','ينجز خريطة بسيطة للقسم بثلاثة رموز.'],prior:'الاتجاهات الأربعة والتعامل مع الرسوم.',steps:[['وضعية الانطلاق',5,'عرض خريطة بدون مفتاح لاكتشاف صعوبة فهم الرموز.'],['بناء التعلمات',15,'البحث عن العنوان والمفتاح وتحديد وظيفة كل واحد.'],['الاستثمار والتمرين',10,'قراءة رموز خريطة جديدة في ثنائيات.'],['التقويم',10,'رسم خريطة للقسم وكتابة مفتاحها.'],['الدعم',5,'بطاقات ربط الرمز بالمعنى.']]},
  {id:'carry',title:'الجمع بالاحتفاظ',level:'الرياضيات · ابتدائي',duration:45,objective:['يجمع عددين من رقمين بالاحتفاظ.','يفسر خطوة الاحتفاظ بوسيلة ملموسة.','يحل مسألة بسيطة تتطلب جمعًا بالاحتفاظ.'],prior:'الجمع بدون احتفاظ وقيمة العشرات والآحاد.',steps:[['وضعية الانطلاق',5,'مسألة شراء 27 كراسة ثم 15 كراسة.'],['بناء التعلمات',15,'استعمال حزم وأعواد وتجميع الآحاد في حزمة جديدة.'],['الاستثمار والتمرين',10,'عمليات متدرجة في ثنائيات والتحقق بالوسيلة.'],['التقويم',10,'عمليتان ومسألة فردية.'],['الدعم',5,'إعادة التجميع بوسيلة محسوسة.']]}
